const n = BigInt(input[0]);
const k = BigInt(input[1]);

// Precompute factorials up to 20! (since 20! > 1e18)
const maxFact = 20;
const fact = [1n];
for (let i = 1n; i <= BigInt(maxFact); i++) {
    fact[i] = fact[i - 1n] * i;
}

// Check if k-th permutation exists
let m = 0n;
while (m < BigInt(maxFact) && fact[m + 1n] < k) {
    m++;
}
if (fact[m + 1n] < k) {
    console.log(-1);
    process.exit(0);
}

// Generate the k-th permutation of the last m+1 elements
const perm = [];
const used = new Array(Number(m) + 1).fill(false);
let remaining = k - 1n;

for (let i = 0n; i <= m; i++) {
    const f = fact[m - i];
    let idx = remaining / f;
    remaining = remaining % f;
    let count = 0n;
    for (let j = 0n; j <= m; j++) {
        if (!used[Number(j)]) {
            if (count === idx) {
                perm.push(Number(j) + 1);
                used[Number(j)] = true;
                break;
            }
            count++;
        }
    }
}

